}

const discoveryPass = (
  calls: Array<RawToolCall>,
  workspace: string,
  repositoryRoot: string,
  runStartedAtMs: number,
  startIndex: number
): Effect.Effect<number, ProcessExecutionFailed | ProcessTimedOut> =>
  Effect.gen(function* () {
